from solution import multiples_of_num


def test_issue_example_given():
    """Example asserts multiples_of_num(4,3)==[3,6,9,12]."""
    assert multiples_of_num(4, 3) == [3, 6, 9, 12]  # 3*1=3, 3*2=6, 3*3=9, 3*4=12


def test_issue_single_multiple():
    """Find m number of multiples of n with m=1."""
    assert multiples_of_num(1, 7) == [7]  # 7*1=7


def test_issue_two_multiples():
    """Find m number of multiples of n with m=2."""
    assert multiples_of_num(2, 5) == [5, 10]  # 5*1=5, 5*2=10


def test_issue_five_multiples_of_two():
    """Find m number of multiples of n for five multiples of 2."""
    assert multiples_of_num(5, 2) == [2, 4, 6, 8, 10]  # 2*1=2, 2*2=4, 2*3=6, 2*4=8, 2*5=10


def test_issue_multiples_of_one():
    """Find m number of multiples of n when n is 1."""
    assert multiples_of_num(3, 1) == [1, 2, 3]  # 1*1=1, 1*2=2, 1*3=3


def test_issue_larger_n():
    """Find m number of multiples of n for larger n."""
    assert multiples_of_num(3, 10) == [10, 20, 30]  # 10*1=10, 10*2=20, 10*3=30


def test_issue_zero_count_empty():
    """Find m number of multiples of n with m=0 gives empty."""
    assert multiples_of_num(0, 3) == []  # 0 requested so 0 entries


def test_issue_first_is_n():
    """Find m number of multiples of n starting at n."""
    assert multiples_of_num(4, 5)[0] == 5  # 5*1=5


def test_issue_last_is_m_times_n():
    """Find m number of multiples of n ending at m times n."""
    assert multiples_of_num(4, 5)[-1] == 20  # 4*5=20


def test_contract_returns_list():
    """Example shows result is list [3,6,9,12]."""
    assert isinstance(multiples_of_num(4, 3), list)  # expect list type


def test_contract_length_equals_m():
    """Find m number of multiples of n means length is m."""
    assert len(multiples_of_num(6, 4)) == 6  # m=6 so 6 entries


def test_contract_step_equals_n():
    """Multiples of n differ by n."""
    result = multiples_of_num(4, 3)  # 3*1=3, 3*2=6, 3*3=9, 3*4=12
    assert all(b - a == 3 for a, b in zip(result, result[1:]))  # 6-3=3, 9-6=3, 12-9=3
